<?php
require __DIR__.'/../app/bootstrap.php';$adminId=require_admin();
if (!db_table_exists('destination_catalog')) redirect('upgrade.php');$pdo=db();$upload=new UploadService(dirname(__DIR__));$success=flash('success');$error=flash('error');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);if($action==='delete'&&$id){$pdo->prepare('UPDATE destination_catalog SET status="archived" WHERE id=?')->execute([$id]);flash('success','Destination archived.');redirect('admin/destinations.php');}
$name=trim((string)($_POST['name']??''));if($name==='')throw new InvalidArgumentException('Destination name is required.');$slug=trim((string)($_POST['slug']??''));if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'));$image=trim((string)($_POST['hero_image_url']??''));if(!empty($_FILES['hero_image']['name'])){$image=$upload->storeImage($_FILES['hero_image'],$adminId,'destinations',600,320)??$image;}
$hasGeo=db_column_exists('destination_catalog','latitude');$latitude=($_POST['latitude']??'')!==''?(float)$_POST['latitude']:null;$longitude=($_POST['longitude']??'')!==''?(float)$_POST['longitude']:null;$data=[$slug,$name,trim((string)($_POST['city']??'')),trim((string)($_POST['region']??'')),trim((string)($_POST['country']??'')),trim((string)($_POST['short_description']??'')),trim((string)($_POST['description']??'')),$image,trim((string)($_POST['best_for']??'')),trim((string)($_POST['vibe']??'')),(string)($_POST['status']??'draft'),isset($_POST['featured'])?1:0,(int)($_POST['sort_order']??0)];
if($id){if($hasGeo){$stmt=$pdo->prepare('UPDATE destination_catalog SET slug=?,name=?,city=?,region=?,country=?,short_description=?,description=?,hero_image_url=?,best_for=?,vibe=?,status=?,featured=?,sort_order=?,latitude=?,longitude=? WHERE id=?');$stmt->execute([...$data,$latitude,$longitude,$id]);}else{$stmt=$pdo->prepare('UPDATE destination_catalog SET slug=?,name=?,city=?,region=?,country=?,short_description=?,description=?,hero_image_url=?,best_for=?,vibe=?,status=?,featured=?,sort_order=? WHERE id=?');$stmt->execute([...$data,$id]);}}else{if($hasGeo){$stmt=$pdo->prepare('INSERT INTO destination_catalog (slug,name,city,region,country,short_description,description,hero_image_url,best_for,vibe,status,featured,sort_order,latitude,longitude) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([...$data,$latitude,$longitude]);}else{$stmt=$pdo->prepare('INSERT INTO destination_catalog (slug,name,city,region,country,short_description,description,hero_image_url,best_for,vibe,status,featured,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute($data);}}flash('success','Destination saved.');redirect('admin/destinations.php');}catch(Throwable $e){flash('error',$e->getMessage());redirect('admin/destinations.php');}}
$edit=null;if(isset($_GET['edit'])){$stmt=$pdo->prepare('SELECT * FROM destination_catalog WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch()?:null;}$rows=$pdo->query('SELECT * FROM destination_catalog ORDER BY status="active" DESC,featured DESC,sort_order,name')->fetchAll();$title='Destinations — Admin';require __DIR__.'/../partials/header.php';
?>
<section class="dashboard"><div class="shell"><div class="dashboard-head"><div><div class="eyebrow">Admin · Destinations</div><h1>Destination catalog</h1><p class="muted">Manage the browse-first destinations shown inside Vacation Brain.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="button primary small" href="<?=e(app_url('admin/destination-ai-create.php'))?>">AI Create Destination</a><a class="button secondary small" href="<?=e(app_url('destinations.php'))?>">View listing</a></div></div><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="admin-split"><form class="dashboard-card stack" method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><h2><?=$edit?'Edit destination':'Add destination'?></h2><label>Name<input class="input" name="name" value="<?=e($edit['name']??'')?>" required></label><label>Slug<input class="input" name="slug" value="<?=e($edit['slug']??'')?>"></label><div class="form-grid"><label>City<input class="input" name="city" value="<?=e($edit['city']??'')?>"></label><label>Region<input class="input" name="region" value="<?=e($edit['region']??'')?>"></label><label>Country<input class="input" name="country" value="<?=e($edit['country']??'')?>"></label></div><?php if(db_column_exists('destination_catalog','latitude')):?><div class="form-grid two"><label>Latitude<input class="input" type="number" step="0.0000001" name="latitude" value="<?=e((string)($edit['latitude']??''))?>"></label><label>Longitude<input class="input" type="number" step="0.0000001" name="longitude" value="<?=e((string)($edit['longitude']??''))?>"></label></div><?php endif;?><label>Short description<textarea class="input" name="short_description" rows="3"><?=e($edit['short_description']??'')?></textarea></label><label>Full description<textarea class="input" name="description" rows="5"><?=e($edit['description']??'')?></textarea></label><label>Best for<input class="input" name="best_for" value="<?=e($edit['best_for']??'')?>"></label><label>Vibe<input class="input" name="vibe" value="<?=e($edit['vibe']??'')?>"></label><label>Hero image URL<input class="input" name="hero_image_url" value="<?=e($edit['hero_image_url']??'')?>"></label><label>Or upload hero image<input class="input" type="file" name="hero_image" accept="image/jpeg,image/png,image/webp"></label><div class="form-grid"><label>Status<select class="input" name="status"><?php foreach(['draft','active','archived'] as $s):?><option value="<?=$s?>" <?=($edit['status']??'active')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></label><label>Sort order<input class="input" type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label></div><label class="check-row"><input type="checkbox" name="featured" <?=!empty($edit['featured'])?'checked':''?>> Featured destination</label><button class="button primary">Save destination</button></form>
<div class="dashboard-card"><h2>Destinations</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Status</th><th>Featured</th><th></th></tr></thead><tbody><?php foreach($rows as $d):?><tr><td><strong><?=e($d['name'])?></strong><br><small class="muted"><?=e(trim(implode(', ',array_filter([$d['city'],$d['country']]))))?></small><?php if(!empty($d['is_sample'])):?><br><span class="sample-badge">Sample</span><?php endif;?></td><td><?=e($d['status'])?></td><td><?=$d['featured']?'Yes':'—'?></td><td><div class="table-actions"><a href="?edit=<?=(int)$d['id']?>">Edit</a><?php if(db_table_exists('destination_prompt_profiles')):?><a href="<?=e(app_url('admin/destination-prompts.php?id='.(int)$d['id']))?>">Prompt Library</a><?php endif;?><?php if(db_table_exists('destination_reports')):?><a href="<?=e(app_url('destination-report.php?destination_id='.(int)$d['id']))?>">Report</a><?php endif;?><a href="<?=e(app_url('vacation-yourself.php?destination_id='.(int)$d['id']))?>">Show Me There</a></div></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section>
